#' Plot One-Way Sensitivity Analysis Tornado Diagrams
#'
#' Produces tornado diagrams from deterministic one-way sensitivity
#' analysis results generated by compute_owsa().
#'
#' Supports multiple datasets, comparisons, subgroups, willingness-to-pay
#' thresholds, and independent plots using plot_by.
#'
#' @param data An object of class "owsa_result".
#' @param metric Economic outcome to represent. One of:
#'   \itemize{
#'     \item \code{"icer"}: incremental cost-effectiveness ratio.
#'     \item \code{"nmb"}: incremental net monetary benefit.
#'     \item \code{"delta_cost"}: incremental cost.
#'     \item \code{"delta_effect"}: incremental effectiveness.
#'   }
#'   The willingness-to-pay threshold \code{lambda} is used only
#'   when \code{metric = "nmb"}. For all other metrics, any supplied
#'   \code{lambda} is ignored with an informational warning.
#'
#' @param lambda Optional willingness-to-pay threshold for NMB plots.
#'   When multiple thresholds are available, one must be selected
#'   if \code{metric = "nmb"}. Ignored for all other metrics.
#' @param impact_mode Either "absolute" or "relative".
#' @param shape_by Dimension mapped to bar outline linetypes. NULL uses
#'   "dataset"; "none" disables linetype grouping.
#' @param facet_by Faceting directive: "none", "dataset",
#'   "comparison", "subgroup_var", "subgroup_level", or "subgroup".
#'   NULL uses "none" in Overall mode and "subgroup" in Subgroups mode.
#' @param plot_by Dimension used to generate independent plots:
#'   "none", "dataset", "comparison", "subgroup_var",
#'   or "subgroup_level". NULL defaults to "comparison".
#' @param mode Either "Overall" or "Subgroups".
#' @param filter_expr Optional filtering expression.
#' @param facet_scales Facet scaling behaviour.
#' @param palette Named colours for lower and upper scenarios.
#' @param shapes_palette Optional object of class "cea_shapes".
#' @param alpha Bar fill opacity, between 0 and 1.
#' @param return_data Return plotting data instead of graphs.
#'
#' @details
#' In relative mode, scenario values are represented as changes
#' from their corresponding analytical baseline:
#'
#'   relative impact = scenario value - baseline value
#'
#' The original economic values are preserved in the returned data.
#'
#' Parameter ranking is calculated independently for each plot when
#' plot_by is active. Parameters with zero impact throughout an
#' independent plot are excluded from its graphical representation.
#'
#' When plot_by = "none", a global ranking based on mean impact
#' across analytical combinations is retained.
#'
#' Impact is defined as the maximum absolute deviation from baseline
#' across the lower and upper scenarios.
#'
#' In relative mode, a vertical reference line is drawn at zero.
#' In absolute mode, a vertical reference line is drawn at the
#' baseline only when all series share the same baseline value.
#'
#' By default, independent plots are generated for each comparison.
#' Overall mode does not facet automatically. Subgroups mode facets
#' by subgroup variable and level.
#'
#' @return A ggplot object, a data frame, or a named list of either.
#' @export
#' @rawNamespace export(plot.tornado)
plot.tornado <- function(
    data,
    metric = "nmb",
    lambda = NULL,
    impact_mode = NULL,
    shape_by = NULL,
    facet_by = NULL,
    plot_by = NULL,
    mode = "Overall",
    filter_expr = NULL,
    facet_scales = "free_x",
    palette = c(
      lower = "#4472C4",
      upper = "#C0504D"
    ),
    shapes_palette = NULL,
    alpha = 0.40,
    return_data = FALSE
) {

  `%||%` <- function(a, b) {
    if (!is.null(a)) a else b
  }

  # -------------------------------------------------------------------------
  # 1. Input validation
  # -------------------------------------------------------------------------
  if (!inherits(data, "owsa_result")) {
    stop("'data' must be an owsa_result object.")
  }

  metric <- match.arg(
    metric,
    c("icer", "nmb", "delta_cost", "delta_effect")
  )

  mode <- match.arg(
    mode,
    c("Overall", "Subgroups")
  )

  default_impact <- if (mode == "Subgroups") {
    "relative"
  } else {
    "absolute"
  }

  impact_mode <- impact_mode %||% default_impact

  impact_mode <- match.arg(
    impact_mode,
    c("absolute", "relative")
  )

  allowed_facets <- c(
    "none",
    "comparison",
    "dataset",
    "subgroup",
    "subgroup_var",
    "subgroup_level"
  )

  allowed_plot_by <- c(
    "none",
    "dataset",
    "comparison",
    "subgroup_var",
    "subgroup_level"
  )

  allowed_shapes <- c(
    "none",
    "dataset",
    "comparison",
    "subgroup_var",
    "subgroup_level"
  )

  validate_directive <- function(value, allowed, argument) {

    if (is.null(value)) {
      return(invisible(TRUE))
    }

    if (!is.character(value) ||
        length(value) != 1L ||
        is.na(value) ||
        !value %in% allowed) {
      stop(
        "'", argument, "' must be a single value among: ",
        paste(allowed, collapse = ", ")
      )
    }

    invisible(TRUE)
  }

  validate_directive(
    facet_by, allowed_facets, "facet_by"
  )

  validate_directive(
    plot_by, allowed_plot_by, "plot_by"
  )

  validate_directive(
    shape_by, allowed_shapes, "shape_by"
  )

  if (!is.character(facet_scales) ||
      length(facet_scales) != 1L ||
      is.na(facet_scales) ||
      !facet_scales %in% c(
        "fixed", "free", "free_x", "free_y"
      )) {
    stop("Invalid 'facet_scales' specification.")
  }

  if (!is.numeric(alpha) ||
      length(alpha) != 1L ||
      is.na(alpha) ||
      !is.finite(alpha) ||
      alpha < 0 ||
      alpha > 1) {
    stop(
      "'alpha' must be a single numeric value between 0 and 1."
    )
  }

  # -------------------------------------------------------------------------
  # 2. Resolve graphical defaults according to mode
  # -------------------------------------------------------------------------
  default_shape <- "dataset"

  default_facet <- if (mode == "Subgroups") {
    "subgroup"
  } else {
    "none"
  }

  default_plot <- "comparison"

  resolved_shape <- shape_by %||% default_shape
  resolved_facet <- facet_by %||% default_facet
  resolved_plot <- plot_by %||% default_plot

  if (identical(resolved_shape, "none")) {
    resolved_shape <- NULL
  }

  expanded_facets <- switch(
    resolved_facet,
    none = character(0),
    subgroup = c("subgroup_var", "subgroup_level"),
    resolved_facet
  )

  # -------------------------------------------------------------------------
  # 3. Resolve metric and willingness-to-pay threshold
  # -------------------------------------------------------------------------
  metric_column <- metric
  selected_lambda <- NULL

  if (metric == "nmb") {

    available_lambda <- data$settings$lambda

    if (is.null(available_lambda) ||
        !is.numeric(available_lambda) ||
        length(available_lambda) == 0L ||
        any(!is.finite(available_lambda))) {
      stop(
        "No valid willingness-to-pay thresholds found ",
        "in data$settings$lambda."
      )
    }

    if (is.null(lambda)) {

      if (length(available_lambda) == 1L) {

        selected_lambda <- available_lambda

      } else {

        stop(
          "Multiple willingness-to-pay thresholds are available: ",
          paste(available_lambda, collapse = ", "),
          ". Specify one using 'lambda'."
        )
      }

    } else {

      if (!is.numeric(lambda) ||
          length(lambda) != 1L ||
          !is.finite(lambda)) {
        stop(
          "'lambda' must be a single finite numeric value."
        )
      }

      if (!lambda %in% available_lambda) {
        stop(
          "The selected lambda is not available. ",
          "Available thresholds: ",
          paste(available_lambda, collapse = ", ")
        )
      }

      selected_lambda <- lambda
    }

    metric_column <- paste0("NMB_", selected_lambda)

  } else {

    # Lambda has no analytical role outside NMB.
    # Ignore it without interrupting plotting.

    if (!is.null(lambda)) {
      warning(
        "'lambda' is ignored when metric = '",
        metric,
        "'. It is only applicable when metric = 'nmb'.",
        call. = FALSE
      )
    }
  }

  # -------------------------------------------------------------------------
  # 4. Extract and filter results
  # -------------------------------------------------------------------------
  df <- data$sensitivity_results

  required <- c(
    "dataset",
    "subgroup_var",
    "subgroup_level",
    "comparison",
    "parameter",
    "scenario",
    metric_column
  )

  if (!all(required %in% names(df))) {
    stop(
      "Missing dimensions or metric column in OWSA results: ",
      paste(
        setdiff(required, names(df)),
        collapse = ", "
      )
    )
  }

  if (!is.null(filter_expr)) {
    df <- dplyr::filter(
      df,
      !!rlang::parse_expr(filter_expr)
    )
  }

  if (mode == "Overall") {

    df <- df[
      df$subgroup_var == "Overall" |
        is.na(df$subgroup_var),
      ,
      drop = FALSE
    ]

  } else {

    df <- df[
      df$subgroup_var != "Overall" &
        !is.na(df$subgroup_var),
      ,
      drop = FALSE
    ]
  }

  if (nrow(df) == 0L) {
    stop("No observations available after filtering.")
  }

  # -------------------------------------------------------------------------
  # 5. Prepare complete sensitivity scenarios
  # -------------------------------------------------------------------------
  keys <- c(
    "dataset",
    "subgroup_var",
    "subgroup_level",
    "comparison",
    "parameter"
  )

  if (anyNA(df[c(keys, "scenario")])) {
    stop("Missing analytical identifiers or scenarios.")
  }

  if (anyDuplicated(df[c(keys, "scenario")])) {
    stop(
      "Duplicated OWSA results for an analytical combination."
    )
  }

  extract_scenario <- function(scenario, value_name) {

    out <- df[
      df$scenario == scenario,
      c(keys, metric_column),
      drop = FALSE
    ]

    names(out)[ncol(out)] <- value_name

    out
  }

  baseline <- extract_scenario("baseline", "baseline")
  lower <- extract_scenario("lower", "lower_value")
  upper <- extract_scenario("upper", "upper_value")

  tornado <- merge(
    merge(baseline, lower, by = keys),
    upper,
    by = keys
  )

  if (nrow(tornado) == 0L ||
      nrow(tornado) != nrow(baseline) ||
      nrow(tornado) != nrow(lower) ||
      nrow(tornado) != nrow(upper)) {
    stop("Incomplete sensitivity scenarios detected.")
  }

  tornado$impact <- pmax(
    abs(tornado$lower_value - tornado$baseline),
    abs(tornado$upper_value - tornado$baseline)
  )

  # -------------------------------------------------------------------------
  # 6. Prepare long-format plotting data
  # -------------------------------------------------------------------------
  tornado_long <- dplyr::bind_rows(
    dplyr::mutate(
      tornado,
      scenario = "lower",
      value = lower_value
    ),
    dplyr::mutate(
      tornado,
      scenario = "upper",
      value = upper_value
    )
  )

  tornado_long$scenario <- factor(
    tornado_long$scenario,
    levels = c("lower", "upper")
  )

  # -------------------------------------------------------------------------
  # 7. Resolve absolute or relative impact representation
  # -------------------------------------------------------------------------
  if (impact_mode == "relative") {

    tornado_long$plot_baseline <- 0

    tornado_long$plot_value <-
      tornado_long$value - tornado_long$baseline

  } else {

    tornado_long$plot_baseline <- tornado_long$baseline
    tornado_long$plot_value <- tornado_long$value
  }

  tornado_long$segment_start <- tornado_long$plot_baseline
  tornado_long$segment_end <- tornado_long$plot_value

  # -------------------------------------------------------------------------
  # 8. Resolve scenario colours
  # -------------------------------------------------------------------------
  if (is.null(palette)) {
    palette <- c(
      lower = "#4472C4",
      upper = "#C0504D"
    )
  }

  if (length(palette) == 1L &&
      palette %in% rownames(
        RColorBrewer::brewer.pal.info
      )) {

    palette <- RColorBrewer::brewer.pal(
      3,
      palette
    )[1:2]
  }

  if (is.null(names(palette))) {

    if (length(palette) != 2L) {
      stop(
        "'palette' must contain exactly two colours."
      )
    }

    names(palette) <- c("lower", "upper")
  }

  if (!all(c("lower", "upper") %in% names(palette))) {
    stop(
      "'palette' must define 'lower' and 'upper'."
    )
  }

  palette <- palette[c("lower", "upper")]

  # -------------------------------------------------------------------------
  # 9. Prepare labels shared by all plots
  # -------------------------------------------------------------------------
  metric_labels <- c(
    icer = "Incremental cost-effectiveness ratio",
    nmb = "Net monetary benefit",
    delta_cost = "Incremental cost",
    delta_effect = "Incremental effect"
  )

  subtitle_base <- paste(
    "Outcome:",
    metric_labels[[metric]]
  )

  if (metric == "nmb" && impact_mode == "absolute") {

    formatted_lambda <- format(
      selected_lambda,
      big.mark = ",",
      scientific = FALSE,
      trim = TRUE
    )

    subtitle_base <- paste0(
      subtitle_base,
      " (lambda = ",
      formatted_lambda,
      ")"
    )
  }

  if (impact_mode == "relative") {

    subtitle_base <- paste0(
      subtitle_base,
      " | Change from baseline"
    )
  }

  x_label <- switch(
    metric,
    nmb = if (impact_mode == "relative")
      "Change in net monetary benefit (cost units)"
    else
      "Net monetary benefit",
    delta_cost = if (impact_mode == "relative")
      "Change in incremental cost (cost units)"
    else
      "Incremental cost",
    delta_effect = if (impact_mode == "relative")
      "Change in incremental effect (effect units)"
    else
      "Incremental effect",
    icer = if (impact_mode == "relative")
      "Change in ICER (cost/effect units)"
    else
      "ICER"
  )

  # -------------------------------------------------------------------------
  # 10. Internal function: rank parameters for one plot
  # -------------------------------------------------------------------------
  rank_plot_data <- function(
    plot_df,
    independent = FALSE
  ) {

    # In independent plots, remove parameters with no impact
    # across all analytical combinations in that plot.
    # Combined plots retain every parameter.

    if (independent) {

      parameter_impacts <- stats::aggregate(
        impact ~ parameter,
        data = plot_df,
        FUN = max
      )

      active_parameters <- as.character(
        parameter_impacts$parameter[
          !is.na(parameter_impacts$impact) &
            parameter_impacts$impact > 0
        ]
      )

      # If every parameter has zero impact, retain the data
      # so that an empty plot is not generated.
      if (length(active_parameters) > 0L) {

        plot_df <- plot_df[
          as.character(plot_df$parameter) %in%
            active_parameters,
          ,
          drop = FALSE
        ]
      }
    }

    # Calculate ranking using only the current plot's data.
    # Global ranking is retained when plot_by = "none".

    ranking <- stats::aggregate(
      impact ~ parameter,
      data = plot_df,
      FUN = mean
    )

    ranking <- ranking[
      order(
        ranking$impact,
        as.character(ranking$parameter)
      ),
      ,
      drop = FALSE
    ]

    parameter_levels <- as.character(
      ranking$parameter
    )

    plot_df$parameter <- factor(
      as.character(plot_df$parameter),
      levels = parameter_levels
    )

    plot_df
  }

  # -------------------------------------------------------------------------
  # 11. Internal function: prepare geometry for one plot
  # -------------------------------------------------------------------------
  prepare_plot_data <- function(plot_df) {

    series_keys <- c(
      "dataset",
      "subgroup_var",
      "subgroup_level",
      "comparison"
    )

    series_table <- unique(
      plot_df[series_keys]
    )

    series_table$.series_id <- as.character(
      do.call(
        interaction,
        c(
          series_table[series_keys],
          list(drop = TRUE, lex.order = TRUE)
        )
      )
    )

    if (length(expanded_facets) == 0L) {

      series_table$.panel_id <- "all"

    } else {

      series_table$.panel_id <- as.character(
        do.call(
          interaction,
          c(
            series_table[expanded_facets],
            list(drop = TRUE, lex.order = TRUE)
          )
        )
      )
    }

    series_table <- series_table[
      order(
        series_table$.panel_id,
        series_table$.series_id
      ),
      ,
      drop = FALSE
    ]

    # Dynamic vertical spacing
    total_band <- 0.60
    fill_ratio <- 0.78

    series_table$.offset <- 0
    series_table$.bar_height <- NA_real_

    for (panel in unique(series_table$.panel_id)) {

      idx <- which(series_table$.panel_id == panel)
      n <- length(idx)

      if (n == 1L) {

        series_table$.offset[idx] <- 0
        series_table$.bar_height[idx] <- 0.16

      } else {

        slot_height <- total_band / n

        series_table$.offset[idx] <- seq(
          from = -total_band / 2 + slot_height / 2,
          to = total_band / 2 - slot_height / 2,
          length.out = n
        )

        series_table$.bar_height[idx] <-
          min(0.16, slot_height * fill_ratio)
      }
    }

    plot_df <- merge(
      plot_df,
      series_table[
        c(
          ".series_id",
          ".offset",
          ".bar_height",
          series_keys
        )
      ],
      by = series_keys,
      sort = FALSE
    )

    plot_df$.y <- as.numeric(
      plot_df$parameter
    ) + plot_df$.offset

    plot_df$.xmin <- pmin(
      plot_df$segment_start,
      plot_df$segment_end
    )

    plot_df$.xmax <- pmax(
      plot_df$segment_start,
      plot_df$segment_end
    )

    plot_df$.ymin <-
      plot_df$.y - plot_df$.bar_height / 2

    plot_df$.ymax <-
      plot_df$.y + plot_df$.bar_height / 2

    plot_df
  }

  # -------------------------------------------------------------------------
  # 12. Internal function: construct one tornado plot
  # -------------------------------------------------------------------------
  build_plot <- function(plot_df, plot_label = NULL) {

    # Parameter labels are local to the current plot.
    parameter_levels <- levels(
      plot_df$parameter
    )

    linetype_values <- NULL

    if (!is.null(resolved_shape)) {

      base <- ce_plot_base(
        data = plot_df,
        color_by = "none",
        shape_by = resolved_shape,
        facet_by = "none",
        palette = "Dark2",
        shapes_palette = shapes_palette
      )

      linetype_values <- base$linetype_values

      levels_shape <- sort(unique(
        as.character(plot_df[[resolved_shape]])
      ))

      if (is.null(shapes_palette) ||
          is.null(shapes_palette$linetypes)) {

        original_linetypes <- c(
          "solid", "dashed", "dotdash", "dotted",
          "longdash", "twodash"
        )

        linetype_values <- stats::setNames(
          rep(
            original_linetypes,
            length.out = length(levels_shape)
          ),
          levels_shape
        )
      }
    }

    p <- ggplot2::ggplot(plot_df) +
      ggplot2::theme_bw() +
      ggplot2::theme(
        panel.grid.major.y = ggplot2::element_blank(),
        panel.grid.minor = ggplot2::element_blank(),
        strip.background = ggplot2::element_rect(
          fill = "grey90",
          colour = NA
        )
      )

    # -----------------------------------------------------------------------
    # Vertical baseline reference
    # -----------------------------------------------------------------------
    reference_value <- NULL

    if (impact_mode == "relative") {

      reference_value <- 0

    } else {

      baseline_values <- unique(plot_df$baseline)

      if (length(baseline_values) == 1L &&
          is.finite(baseline_values)) {

        reference_value <- baseline_values
      }
    }

    if (!is.null(reference_value)) {

      p <- p +
        ggplot2::geom_vline(
          xintercept = reference_value,
          colour = "grey45",
          linetype = "dashed",
          linewidth = 0.5
        )
    }

    # -----------------------------------------------------------------------
    # Tornado bars
    # -----------------------------------------------------------------------
    rect_mapping <- ggplot2::aes(
      xmin = .xmin,
      xmax = .xmax,
      ymin = .ymin,
      ymax = .ymax,
      fill = scenario,
      colour = scenario
    )

    if (!is.null(resolved_shape)) {
      rect_mapping$linetype <- rlang::sym(
        resolved_shape
      )
    }

    p <- p +
      ggplot2::geom_rect(
        mapping = rect_mapping,
        linewidth = 0.8
      ) +
      ggplot2::scale_fill_manual(
        values = scales::alpha(palette, alpha),
        name = "Scenario"
      ) +
      ggplot2::scale_colour_manual(
        values = palette,
        name = "Scenario",
        guide = "none"
      )

    if (!is.null(resolved_shape)) {
      p <- p +
        ggplot2::scale_linetype_manual(
          values = linetype_values,
          name = resolved_shape
        )
    }

    # -----------------------------------------------------------------------
    # Linetype legend
    # -----------------------------------------------------------------------
    if (!is.null(resolved_shape)) {

      n_shape_levels <- dplyr::n_distinct(
        plot_df[[resolved_shape]],
        na.rm = TRUE
      )

      if (n_shape_levels > 1L) {

        p <- p +
          ggplot2::guides(
            linetype = ggplot2::guide_legend(
              title = resolved_shape,
              override.aes = list(
                colour = "grey20",
                fill = NA,
                linewidth = 0.8
              )
            )
          )

      } else {

        p <- p +
          ggplot2::guides(
            linetype = "none"
          )
      }
    }

    # -----------------------------------------------------------------------
    # Faceting
    # -----------------------------------------------------------------------
    if (resolved_facet == "subgroup") {

      p <- p +
        ggplot2::facet_grid(
          rows = ggplot2::vars(subgroup_level),
          cols = ggplot2::vars(subgroup_var),
          scales = facet_scales
        )

    } else if (resolved_facet %in% c(
      "dataset",
      "comparison",
      "subgroup_var",
      "subgroup_level"
    )) {

      p <- p +
        ggplot2::facet_wrap(
          ggplot2::vars(!!rlang::sym(resolved_facet)),
          scales = facet_scales
        )
    }

    subtitle <- subtitle_base

    if (!is.null(plot_label)) {
      subtitle <- paste0(
        subtitle,
        " | ",
        resolved_plot,
        ": ",
        plot_label
      )
    }

    p <- p +
      ggplot2::scale_y_continuous(
        breaks = seq_along(parameter_levels),
        labels = parameter_levels,
        expand = ggplot2::expansion(add = 0.55)
      ) +
      ggplot2::labs(
        title = "One-Way Sensitivity Analysis",
        subtitle = subtitle,
        x = x_label,
        y = NULL
      )

    p
  }

  # -------------------------------------------------------------------------
  # 13. Resolve independent plots
  # -------------------------------------------------------------------------
  if (resolved_plot == "none") {

    # Combined plot: preserve global ranking.
    plot_df <- rank_plot_data(
      tornado_long,
      independent = FALSE
    )

    plot_df <- prepare_plot_data(plot_df)

    if (return_data) {
      return(plot_df)
    }

    return(build_plot(plot_df))
  }

  # Independent plots: each plot receives its own ranking.
  plot_levels <- unique(
    as.character(tornado_long[[resolved_plot]])
  )

  plot_levels <- sort(plot_levels)

  output <- vector(
    mode = "list",
    length = length(plot_levels)
  )

  names(output) <- plot_levels

  for (level in plot_levels) {

    plot_df <- tornado_long[
      as.character(tornado_long[[resolved_plot]]) == level,
      ,
      drop = FALSE
    ]

    plot_df <- rank_plot_data(
      plot_df,
      independent = TRUE
    )

    plot_df <- prepare_plot_data(plot_df)

    if (return_data) {

      output[[level]] <- plot_df

    } else {

      output[[level]] <- build_plot(
        plot_df,
        plot_label = level
      )
    }
  }

  # -------------------------------------------------------------------------
  # 14. Interactive multiple plots handler
  # -------------------------------------------------------------------------
  if (!return_data && resolved_plot != "none") {

    output <- cea_multplots_handler(
      output,
      plot_type = "Tornado plot"
    )
  }

  return(output)
}
